CREATE TABLE `Discount_Coupons` (`coupon_id` DECIMAL(18,2), `date_issued` DATETIME, `coupon_amount` DECIMAL(18,2));
CREATE TABLE `Customers` (`customer_id` DECIMAL(18,2), `coupon_id` DECIMAL(18,2), `good_or_bad_customer` VARCHAR(100), `first_name` VARCHAR(100), `last_name` VARCHAR(100), `gender_mf` VARCHAR(100), `date_became_customer` DATETIME, `date_last_hire` DATETIME);
CREATE TABLE `Bookings` (`booking_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `booking_status_code` VARCHAR(100), `returned_damaged_yn` VARCHAR(100), `booking_start_date` DATETIME, `booking_end_date` DATETIME, `count_hired` VARCHAR(100), `amount_payable` DECIMAL(18,2), `amount_of_discount` DECIMAL(18,2), `amount_outstanding` DECIMAL(18,2), `amount_of_refund` DECIMAL(18,2));
CREATE TABLE `Products_for_Hire` (`product_id` DECIMAL(18,2), `product_type_code` VARCHAR(100), `daily_hire_cost` DECIMAL(18,2), `product_name` VARCHAR(100), `product_description` VARCHAR(100));
CREATE TABLE `Payments` (`payment_id` DECIMAL(18,2), `booking_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `payment_type_code` VARCHAR(100), `amount_paid_in_full_yn` VARCHAR(100), `payment_date` DATETIME, `amount_due` DECIMAL(18,2), `amount_paid` DECIMAL(18,2));
CREATE TABLE `Products_Booked` (`booking_id` DECIMAL(18,2), `product_id` DECIMAL(18,2), `returned_yn` VARCHAR(100), `returned_late_yn` VARCHAR(100), `booked_count` DECIMAL(18,2), `booked_amount` DECIMAL(18,2));
CREATE TABLE `View_Product_Availability` (`product_id` DECIMAL(18,2), `booking_id` DECIMAL(18,2), `status_date` DATETIME, `available_yn` VARCHAR(100));
